mixedDeclaredWaterlineTypes.sql:
CREATE TABLE t(
    a TINYINT LATENESS 1, b SMALLINT LATENESS 2, c INTEGER LATENESS 3, d BIGINT LATENESS 4,
    e DECIMAL(4,4) LATENESS 0.0050, f REAL LATENESS CAST(1 AS REAL), g DOUBLE LATENESS CAST(2 AS DOUBLE),
    h DATE LATENESS INTERVAL '1' DAY, i TIME LATENESS INTERVAL '2' SECOND,
    j TIMESTAMP LATENESS INTERVAL '1' MONTH, k TIMESTAMP WITH TIME ZONE LATENESS INTERVAL '1' DAY
);
CREATE VIEW v AS SELECT * FROM t;
